#[test]
fn guardoptsmoke_language_instantiates() {
    let lang = GuardOptSmokeLanguage;
    assert_eq!(lang.name(), "GuardOptSmoke");
}

#[test]
fn guardoptsmoke_metadata_populated() {
    let lang = GuardOptSmokeLanguage;
    let meta = lang.metadata();
    assert!(!meta.types().is_empty(), "language should have at least one type");
    assert!(!meta.terms().is_empty(), "language should have at least one term");
}

#[test]
fn unit_guardoptsmoke_proc_pnil() {
    let term = Proc::PNil;
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for PNil");
    if let Ok(parsed) = Proc::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(
            displayed, re_displayed,
            "Roundtrip failed for PNil: {} != {}",
            displayed, re_displayed
        );
    }
}

#[test]
fn unit_guardoptsmoke_int_pcheck() {
    mettail_runtime::clear_var_cache();
    let term =
        Int::PCheck(std::sync::Arc::new(Int::NumLit(0i64)), mettail_runtime::BehavioralPred::Top);
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for PCheck");
    if let Ok(parsed) = Int::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(
            displayed, re_displayed,
            "Roundtrip failed for PCheck: {} != {}",
            displayed, re_displayed
        );
    }
}

#[test]
fn unit_guardoptsmoke_auto_proc_pvar() {
    mettail_runtime::clear_var_cache();
    let term = Proc::PVar(mettail_runtime::OrdVar(mettail_runtime::Var::Free(
        mettail_runtime::get_or_create_var("a"),
    )));
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for PVar");
}

